```python
NEIGHBOURS = {"WA": ["NT", "SA"], "NT": ["WA", "SA", "Q"], "SA": ["WA", "NT", "Q", "NSW"],
              "Q": ["NT", "SA", "NSW"], "NSW": ["Q", "SA"]}
COLOURS = ["red", "green", "blue"]
stats = {"assignments": 0, "backtracks": 0}

def solve(assign, domains):
    if len(assign) == len(NEIGHBOURS):
        return assign
    var = min((v for v in NEIGHBOURS if v not in assign), key=lambda v: len(domains[v]))  # MRV.
    for colour in domains[var]:
        stats["assignments"] += 1
        new = {v: [c for c in d if not (v in NEIGHBOURS[var] and c == colour)] for v, d in domains.items()}
        new[var] = [colour]                                   # forward checking.
        if all(new[v] for v in NEIGHBOURS if v not in assign):
            result = solve({**assign, var: colour}, new)
            if result: return result
        stats["backtracks"] += 1                              # undo: try next colour.
    return None

sol = solve({}, {v: COLOURS[:] for v in NEIGHBOURS})
ok = all(sol[a] != sol[b] for a in NEIGHBOURS for b in NEIGHBOURS[a])   # validate every edge.
print(sol, ok, stats)
```

